design.css:
/* Starlight. Web values are the reference site's computed styles at 1600 px; the TV block
   (:scope[data-surface="tv"]) sizes from a 1920 canvas through --u. */
:scope { --theme-top-row: 64px; --sl-page: #17171b; --sl-tile: #2d2f36; --sl-back: #080809; --sl-grey: #dbdcde; }

/* ── Top bar: a 64 px glass bar (blur 25 px) over a 2 px gradient hairline; the profile on the left, icon +
   label destinations centred 36 px apart at 70% until active, a 36 px round search button on the right. ── */
[data-slot="nav.top"] {
  column-gap: 0 !important; padding: 32px 24px 0 !important; border: 0 !important; background: transparent !important;
  -webkit-backdrop-filter: blur(25px); backdrop-filter: blur(25px);
}
[data-slot="nav.top"]::after { content: ""; position: absolute; right: 0; bottom: 0; left: 0; height: 2px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2) 20%, rgba(255, 255, 255, 0.2) 80%, transparent); pointer-events: none; }
/* The bar's three cells: izumi's brand at the start, the destinations in the centred middle column. */
[data-slot="nav.top"] > div:nth-child(2) { order: -1; justify-self: start; }
[data-slot="nav.top"] > div:has(> [data-part="nav.item"]) { gap: 36px !important; overflow: visible !important; }
[data-slot="nav.top"] > div:has(> [data-part="nav.action"]) { gap: 8px !important; padding-right: 52px; }
[data-slot="nav.top"] [data-part="nav.item"] {
  height: 64px; padding: 0 !important; gap: 8px !important; border-radius: 0 !important; background: transparent !important;
  color: #fff !important; opacity: 0.7; font-size: 15px !important; font-weight: 700 !important; line-height: 24px; letter-spacing: 0.11px;
  transition: opacity 0.2s ease-in-out;
}
[data-slot="nav.top"] [data-part="nav.item"]:hover, [data-slot="nav.top"] [data-part="nav.item"][data-active] { opacity: 1; }
[data-slot="nav.top"] [data-part="nav.item.icon"], [data-slot="nav.top"] [data-part="nav.item.icon"] svg { width: 24px !important; height: 24px !important; }
[data-slot="nav.top"] [data-part="nav.item.icon"] svg { animation: none !important; }
/* Search: a 36 px round button at the right end, white with a black glyph while Search is open. */
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"] {
  position: absolute; right: 24px; bottom: 14px; width: 36px; height: 36px; justify-content: center;
  border-radius: 50% !important; background: rgba(45, 47, 54, 0.5) !important; opacity: 1; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out;
}
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"] [data-part="nav.item.label"] { display: none; }
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"] [data-part="nav.item.icon"] { opacity: 0.7; }
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"]:hover [data-part="nav.item.icon"] { opacity: 1; }
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"][data-active] { background: #fff !important; color: #000 !important; }
[data-slot="nav.top"] [data-part="nav.item"][data-dest="search"][data-active] [data-part="nav.item.icon"] { opacity: 1; }
/* Incognito and Settings stay as quiet icons; the profile (36 px round avatar + its name) moves left. */
[data-slot="nav.top"] [data-part="nav.action"] { border-radius: 50% !important; color: #fff !important; opacity: 0.7; background: transparent !important; }
[data-slot="nav.top"] [data-part="nav.action"]:hover, [data-slot="nav.top"] [data-part="nav.action"][data-active] { opacity: 1; }
[data-slot="nav.top"] [data-part="nav.action"][data-action="account"] {
  position: absolute; left: 150px; bottom: 14px; width: auto !important; height: 36px !important; gap: 12px; padding: 0 20px 0 0 !important;
  display: flex !important; border-radius: 18px !important; opacity: 1;
}
[data-slot="nav.top"] [data-action="account"] img { width: 36px !important; height: 36px !important; border-radius: 50% !important; }
[data-slot="nav.top"] [data-action="account"] [data-part="nav.action.label"] {
  position: static; width: auto; height: auto; margin: 0; overflow: visible; clip: auto; white-space: nowrap;
  color: var(--sl-grey); font-size: 15px; font-weight: 400; line-height: 24px;
}
/* Over a series page's art the bar is clear until the page scrolls. */
:scope:has([data-slot="detail"]) [data-slot="nav.top"]:not([data-scrolled]) { -webkit-backdrop-filter: none; backdrop-filter: none; }
:scope:has([data-slot="detail"]) [data-slot="nav.top"]:not([data-scrolled])::after { opacity: 0; }

/* ── Home hero: full-bleed 16:9 art running ~340 px (21.45vw) under the first row, the radial scrim, the
   copy at x=71 above the rows. ── */
@media (min-width: 641px) {
  [data-slot="home.hero"][data-variant="template"] { --hero-bleed: 21.77vw !important; margin-top: calc(-1 * var(--theme-shell-top, 0px)) !important; margin-bottom: calc(-1 * var(--hero-bleed)) !important; }
  [data-part="starlight.info"] { width: calc(510px + 142px) !important; padding: 0 71px calc(var(--hero-bleed) + 8px) !important; }
  [data-slot="home.hero"][data-variant="template"] [data-part="hero.indicator"] { bottom: calc(var(--hero-bleed) - 4px) !important; }
}
[data-part="starlight.hero"]::after { background: radial-gradient(farthest-side at 78% 25%, transparent 30%, #17171b) !important; }
[data-part="starlight.art"] img, [data-part="starlight.logo"] img, [data-part="starlight.card-logo"] img,
[data-part="starlight.poster-art"] img, [data-part="starlight.tile-img"] img, [data-part="starlight.ep-img"] img { transform: none !important; }
[data-part="starlight.badge"] { height: 28px; margin-bottom: 16px; padding: 0 8px; border-radius: 4px; line-height: 28px; white-space: nowrap; }
[data-part="starlight.logo"] { width: 300px; height: 134px; margin-bottom: 12px; }
[data-part="starlight.logo"] img { object-fit: contain !important; object-position: left bottom; }
[data-part="starlight.title"] { margin-bottom: 16px; line-height: 1.1; text-shadow: none !important; }
[data-part="starlight.promo"] { margin-bottom: 8px; color: #fff; line-height: 24px; }
[data-part="starlight.meta"] { margin-bottom: 12px; line-height: 18px; }
[data-part="starlight.rating"] { height: 20px; padding: 0 5px; border-radius: 4px; background: #3e4247; color: #fff; line-height: 20px; white-space: nowrap; }
[data-part="starlight.meta-text"] > *, [data-part="starlight.card-meta"] > *, [data-part="starlight.tile-meta"] > *, [data-part="starlight.promo"] > *, [data-part="starlight.ep-title"] > * { white-space: pre; }
/* The description folds away (1fr → 0fr over .64 s) while the trailer plays. */
[data-part="starlight.desc"] { display: grid !important; grid-template-rows: 1fr; margin-bottom: 24px; transition: grid-template-rows 0.64s ease, margin 0.64s ease, opacity 0.64s ease; }
[data-part="starlight.desc"] > * { min-height: 0; }
[data-part="starlight.synopsis"] { line-height: 32px; }
[data-slot="home.hero"]:has([data-part="hero.video"][data-state="playing"]) [data-part="starlight.desc"] { grid-template-rows: 0fr; margin-bottom: 0; opacity: 0; }
/* DETAILS: a 48 px white pill, black 15/700 caps tracked 1.76 px. */
[data-part="starlight.details"], [data-part="starlight.play"] {
  height: 48px; padding: 0 17px !important; gap: 8px !important; border-radius: 9999px !important; text-transform: uppercase; letter-spacing: 1.76px;
  transition: color 0.2s ease-in-out, background-color 0.2s ease-in-out, border-color 0.2s ease-in-out;
}
[data-part="starlight.details"]:hover { filter: none !important; background: #dbdcde !important; }
/* Dots: 8 px #93959C, the current one a 26 px pill the white fill runs across; 13 px apart. */
[data-slot="home.hero"] [data-part="hero.indicator"] { gap: 13px !important; }
[data-slot="home.hero"] [data-part="hero.dot.track"] { width: 8px !important; height: 8px !important; border-radius: 6px !important; background: #93959c !important; transition: width 0.2s; }
[data-slot="home.hero"] [data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 26px !important; }
[data-slot="home.hero"] [data-part="hero.dot.fill"] { border-radius: 6px; background: #fff !important; }
/* Arrows: 71 px hit areas at both edges, a bare 40 px white chevron that fades in on hover. */
[data-slot="home.hero"] [data-part="hero.edge"] { width: 71px !important; }
[data-slot="home.hero"] [data-part="hero.edge"] > span { width: 40px !important; height: 40px !important; border: 0 !important; background: transparent !important; box-shadow: none !important; transform: none !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; transition: opacity 0.35s !important; }
[data-slot="home.hero"] [data-part="hero.edge"] svg { width: 40px; height: 40px; stroke-width: 1.5; }
/* Loading: the page colour, no shimmer, in the hero's place. */
[data-slot="home.hero"][data-state="loading"] { margin: calc(-1 * var(--theme-shell-top, 0px)) 0 -21.77vw !important; background: var(--sl-page) !important; }
[data-slot="home.hero"][data-state="loading"] > * { display: none; }

/* ── Rows (set-shelf): 22/35.2 #DBDCDE headings at x=71, rows padded 22 px over and 68 px under. ── */
[data-part="row.title"], [data-part="block.title"] { color: var(--sl-grey); font-size: 22px !important; font-weight: 400 !important; line-height: 35.2px; letter-spacing: -0.1px; }
@media (min-width: 641px) {
  [data-part="row.header"] { padding-left: 71px !important; padding-right: 71px !important; }
  [data-part="row.track"] { padding: 12px 71px 28px !important; scroll-padding-inline: 71px !important; }
}
[data-slot="row"] { padding-top: 22px; }
[data-part="row.header"] { margin-bottom: 0 !important; padding-bottom: 0 !important; }
/* Row arrows: 71 px columns at both ends, bare white chevrons. */
[data-part="row.step"] { width: 71px !important; height: auto !important; top: 12px !important; bottom: 28px !important; border: 0 !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; color: #fff !important; -webkit-backdrop-filter: none !important; backdrop-filter: none !important; transform: none !important; transition: opacity 0.35s !important; }
[data-part="row.step"][data-dir="previous"] { left: 0 !important; }
[data-part="row.step"][data-dir="next"] { right: 0 !important; left: auto !important; }
[data-part="row.step"] svg { width: 40px; height: 40px; stroke-width: 1.5; }

/* ── Tiles: 12 px corners on the #080809 backing with a 1 px inset stroke. Hover and focus scale them to 1.03
   (.3 s ease-out), fade a 4 px white ring in 4 px outside the art and drop a soft shadow. ── */
[data-part="starlight.poster"], [data-part="starlight.tile-art"], [data-part="starlight.ep-art"] {
  border-radius: 12px; background: var(--sl-back); outline: 4px solid transparent; outline-offset: 4px;
  transition: transform 0.3s ease-out, box-shadow 0.3s ease-out, outline-color 0.3s ease-out;
}
[data-part="starlight.tile-art"], [data-part="starlight.ep-art"] { background: var(--sl-tile); }
[data-part="starlight.poster"]::after, [data-part="starlight.tile-art"]::after, [data-part="starlight.ep-art"]::after {
  content: ""; grid-area: 1 / 1; z-index: 3; border-radius: inherit; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1); pointer-events: none;
}
[data-part="card"]:hover :is([data-part="starlight.poster"], [data-part="starlight.tile-art"]),
[data-part="card"]:has(:focus-visible) :is([data-part="starlight.poster"], [data-part="starlight.tile-art"]),
[data-part="episode"]:hover [data-part="starlight.ep-art"], [data-part="episode"]:focus-visible [data-part="starlight.ep-art"] {
  transform: scale(1.03); outline-color: #fff; box-shadow: rgba(0, 0, 0, 0.8) 0 20px 24px;
}
[data-part="card"] a:focus-visible, [data-part="episode"]:focus-visible { outline: none !important; box-shadow: none !important; }
/* Poster caption: the title art (218×77, or the title) and the meta line over the poster's bottom. */
[data-part="starlight.cap"] { padding: 72px 12px 16px; background: linear-gradient(to top, rgba(8, 8, 9, 0.85) 0%, rgba(8, 8, 9, 0.55) 55%, transparent); }
[data-part="starlight.card-logo"] { width: 218px; max-width: 80% !important; height: 77px; }
[data-part="starlight.card-logo"] img { object-fit: contain !important; object-position: center bottom; }
[data-part="starlight.card-title"] { line-height: 22px; text-shadow: 0 1px 4px rgba(0, 0, 0, 0.6); }
[data-part="starlight.card-meta"] { justify-content: center; line-height: 18px; }
[data-part="starlight.card-badge"] { height: 24px; padding: 0 6px; border-radius: 4px; line-height: 24px; white-space: nowrap; }
[data-part="starlight.poster"] > [data-part="starlight.card-badge"] { margin: 0 0 12px 12px; align-self: end; justify-self: start; }
[data-part="starlight.tile-art"] > [data-part="starlight.card-badge"] { margin: 10px 0 0 10px; }
/* 16:9 tiles: the title 15/700 and the 12 px meta under the art; a thin white progress line on resume. */
[data-part="starlight.tile-title"] { margin-top: 12px; color: #fff !important; opacity: 1 !important; line-height: 24px; }
[data-part="starlight.tile-meta"] { line-height: 18px; }
[data-part="starlight.tile-bar"] { right: 12px !important; bottom: 12px !important; left: 12px !important; width: auto !important; height: 4px !important; min-height: 4px !important; border-radius: 2px !important; background: rgba(255, 255, 255, 0.25) !important; }
[data-part="starlight.tile-bar"] > span { background: #fff !important; }

/* Row placeholders: flat #080809 tiles with the inset stroke, no shimmer. */
[data-part="row.skeleton"] { width: 273px !important; border-radius: 12px !important; background: var(--sl-back) !important; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1); }
[data-part="row.skeleton"]::before { display: none !important; }
[data-slot="row"]:is([data-role="season"], [data-role="newest"], [data-role="rated"]) [data-part="row.skeleton"] { width: 224px !important; }
[data-slot="row"][data-role="continue"] [data-part="row.skeleton"] { aspect-ratio: 16 / 9; }

/* ── Genre band (tabbed-grid, after the site's brand section): a navy starfield, the collections as a
   tab strip of wordmarks (current one white, 2 px underline) over a hairline; the tagline and BROWSE ALL on
   the left, five posters on the right. ── */
[data-slot="block.tabbed-grid"] {
  display: grid; grid-template-columns: minmax(0, 360px) minmax(0, 1fr); grid-template-rows: auto auto 1fr; column-gap: 48px;
  margin: 22px 0 68px !important; padding: 40px 71px 56px !important;
  background-color: #050935;
  background-image:
    radial-gradient(1.5px 1.5px at 12% 18%, rgba(255, 255, 255, 0.9), transparent),
    radial-gradient(1px 1px at 37% 62%, rgba(255, 255, 255, 0.7), transparent),
    radial-gradient(1px 1px at 68% 27%, rgba(255, 255, 255, 0.8), transparent),
    radial-gradient(1.5px 1.5px at 84% 74%, rgba(255, 255, 255, 0.6), transparent),
    radial-gradient(1px 1px at 52% 88%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(120% 90% at 85% 100%, #1649c8 0%, rgba(22, 73, 200, 0.35) 45%, transparent 75%),
    linear-gradient(180deg, #050935 0%, #0a1561 100%);
  background-size: 230px 230px, 310px 310px, 270px 270px, 390px 390px, 190px 190px, 100% 100%, 100% 100%;
}
[data-slot="block.tabbed-grid"] > div:has(> [data-part="tabs"]) { grid-area: 1 / 1 / 2 / 3; display: flex; justify-content: center; margin-bottom: 40px; }
[data-slot="block.tabbed-grid"] [data-part="tabs"] { margin: 0 !important; padding: 0 !important; gap: 40px !important; border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important; }
[data-slot="block.tabbed-grid"] [data-part="tab"] {
  padding: 0 4px 14px !important; border-radius: 0 !important; background: transparent !important; color: #93959c !important;
  font-size: 22px !important; font-weight: 900 !important; letter-spacing: 1px; text-transform: uppercase; transition: color 0.3s ease-out;
}
[data-slot="block.tabbed-grid"] [data-part="tab"]:hover, [data-slot="block.tabbed-grid"] [data-part="tab"][data-active] { color: #fff !important; }
[data-slot="block.tabbed-grid"] [data-part="tab"] > span { height: 2px !important; bottom: -1px !important; border-radius: 0 !important; background: #fff !important; }
[data-slot="block.tabbed-grid"] > [data-part="block.title"] { grid-area: 2 / 1; align-self: end; margin: 0 0 24px !important; color: #fff; font-size: 28px !important; font-weight: 700 !important; line-height: 36px; }
[data-slot="block.tabbed-grid"] > [data-part="block.grid"] { grid-area: 2 / 2 / 4 / 3; column-gap: 20px !important; row-gap: 24px !important; }
[data-slot="block.tabbed-grid"] > [data-part="pagination"] { grid-area: 3 / 1; align-self: start; justify-content: flex-start !important; margin: 0 !important; }
[data-slot="block.tabbed-grid"] [data-part="block.item"] { animation: starlight-in 0.5s ease-out both; }
[data-slot="block.tabbed-grid"] [data-part="block.grid"] > :not([data-part]) { border-radius: 12px !important; background: var(--sl-back) !important; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1); }
[data-slot="block.tabbed-grid"] [data-part="block.grid"] > :not([data-part])::before { display: none !important; }
/* BROWSE ALL: a translucent 48 px pill. */
[data-slot="block.tabbed-grid"] [data-part="pagination"] [data-part="button"] {
  height: 48px; min-height: 48px !important; padding: 0 24px !important; border-radius: 9999px !important; background: rgba(255, 255, 255, 0.1) !important;
  color: #fff !important; font-size: 0 !important; transition: background-color 0.2s ease-in-out;
}
[data-slot="block.tabbed-grid"] [data-part="pagination"] [data-part="button"]::after { content: "Browse all"; font-size: 15px; font-weight: 700; letter-spacing: 1.76px; line-height: 48px; text-transform: uppercase; }
[data-slot="block.tabbed-grid"] [data-part="pagination"] [data-part="button"]:hover { background: rgba(255, 255, 255, 0.2) !important; }
@keyframes starlight-in { from { opacity: 0; } }

/* ── Series page (stacked under fixed full-bleed art): the art 16:9 behind the page with the radial scrim,
   dimming as the page scrolls; a 550 px column at x=71, 56 px under the bar. ── */
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.banner"] {
  position: fixed !important; top: var(--theme-shell-top, 0px) !important; right: 0; left: 0; z-index: 0;
  height: calc(56.25vw - var(--theme-shell-top, 0px)) !important; margin: 0 !important; --theme-shell-left: 0px;
}
[data-slot="detail.banner"] [data-part="hero.slide"] { opacity: 1 !important; }
[data-slot="detail.banner"] [data-part="hero.art"] { object-position: center top !important; transition: opacity 1s !important; }
[data-slot="detail.banner"] [data-part="hero.scrim"] { width: 100% !important; background: radial-gradient(farthest-side at 73% 21%, transparent, #17171b) !important; }
[data-slot="detail.banner"] [data-part="hero.scrim"] + [data-part="hero.scrim"] { display: none; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] { margin-top: 0 !important; padding: 56px 71px 64px !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.poster"], [data-slot="detail"][data-variant="desktop"] [data-part="detail.alt-title"] { display: none !important; }
[data-slot="detail"][data-variant="desktop"] div:has(> [data-part="detail.title"]) { max-width: 550px; }
/* The info row spans the page over the fixed art: only its column takes the pointer, so the trailer's mute
   button at the art's top right stays clickable. */
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > div:has(> div > [data-part="detail.title"]) { pointer-events: none; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.content"] > div:has(> div > [data-part="detail.title"]) > * { pointer-events: auto; }
[data-slot="detail"] [data-part="detail.title"] { margin-bottom: 16px !important; color: #fafafa; font-size: 48px !important; font-weight: 700 !important; line-height: 1.1; }
[data-slot="detail"] [data-part="detail.logo"] { width: 400px !important; height: 150px !important; max-width: 100% !important; max-height: none !important; object-fit: contain; object-position: left bottom; }
[data-slot="detail"] [data-part="detail.facts"] { margin-bottom: 16px !important; color: var(--sl-grey); line-height: 18px; }
[data-part="starlight.detail-meta"] > * { white-space: pre; }
[data-slot="detail"] [data-part="starlight.rating"] { border: 0; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.synopsis"] { margin-bottom: 24px !important; color: #fff !important; font-size: 20px !important; line-height: 32px !important; -webkit-line-clamp: 4 !important; }
/* ▶ PLAY: a 48 px white pill (black 15/700 caps, 1.76 px tracking, 18 px icon); the other actions 48 px glass circles. */
[data-slot="detail"] [data-part="detail.actions"] { flex-wrap: nowrap !important; width: max-content; gap: 16px !important; }
[data-slot="detail"] [data-part="button"][data-action="play"] {
  height: 48px; padding: 0 24px !important; gap: 8px !important; border-radius: 9999px !important; background: #fff !important; color: #000 !important;
  font-size: 15px !important; font-weight: 700 !important; letter-spacing: 1.76px; text-transform: uppercase; transition: background-color 0.2s ease-in-out;
}
[data-slot="detail"] [data-part="button"][data-action="play"]:hover { background: var(--sl-grey) !important; }
[data-slot="detail"] [data-part="detail.actions"] > :not([data-action="play"]) {
  display: grid !important; place-items: center; width: 48px !important; height: 48px !important; padding: 0 !important; gap: 0 !important; border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.1) !important; color: #fff !important; font-size: 0 !important; -webkit-backdrop-filter: blur(20px); backdrop-filter: blur(20px);
  transition: background-color 0.2s ease-in-out;
}
[data-slot="detail"] [data-part="detail.actions"] > :not([data-action="play"]):hover { background: rgba(255, 255, 255, 0.2) !important; }
[data-slot="detail"] [data-part="detail.actions"] > :not([data-action="play"]) svg { width: 22px; height: 22px; }
[data-slot="detail"] [data-part="detail.list-button"] svg + svg, [data-slot="detail"] [data-part="detail.list-button"] svg:last-child:not(:first-child) { display: none; }
/* Watchlist: a "+" (a check once saved). */
[data-slot="detail"] [data-part="button"][data-action="save"] svg { display: none; }
[data-slot="detail"] [data-part="button"][data-action="save"]::after { content: "+"; font-size: 32px; font-weight: 300; line-height: 1; }
[data-slot="detail"] [data-part="button"][data-action="save"][data-state="saved"]::after { content: "✓"; font-size: 22px; font-weight: 700; }
/* EPISODES · SUGGESTED · DETAILS: 20/28 caps, 2 px tracking; current 700 white with the white underline. */
[data-slot="detail"] [data-part="tabs"] { gap: 48px !important; margin: 48px 0 32px !important; padding: 0 !important; border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important; overflow: visible !important; }
[data-slot="detail"] [data-part="tab"] {
  padding: 0 0 15px !important; border-radius: 0 !important; background: transparent !important; color: var(--sl-grey) !important;
  font-size: 20px !important; font-weight: 400 !important; line-height: 28px; letter-spacing: 2px; text-transform: uppercase; transition: all 0.35s ease !important;
}
[data-slot="detail"] [data-part="tab"]:hover { color: #fff !important; }
[data-slot="detail"] [data-part="tab"][data-active] { color: #fff !important; font-weight: 700 !important; }
[data-slot="detail"] [data-part="tab"] > span { height: 2px !important; bottom: -1px !important; border-radius: 0 !important; background: #fff !important; }
/* Season ⌄: a 35 px #2D2F36 pill, 15 px #DBDCDE. */
[data-part="season.toggle"], [data-slot="episodes.toolbar"] [data-part="episodes.more"] {
  height: 35px !important; padding: 0 16px !important; gap: 8px !important; border: 0 !important; border-radius: 18px !important; background: var(--sl-tile) !important;
  color: var(--sl-grey) !important; font-size: 15px !important; font-weight: 400 !important; box-shadow: none !important;
}
[data-slot="episodes.toolbar"] { margin-bottom: 24px !important; }
[data-slot="episodes.toolbar"] [data-part="episodes.more"] { margin-left: auto; }
/* The tab already names the list: its heading stays for screen readers only. */
[data-slot="detail"] [data-part="episodes.heading"] { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
[data-part="episodes.count"] { display: none; }
[data-part="episodes.menu"] { border: 1px solid rgba(255, 255, 255, 0.1) !important; border-radius: 12px !important; background: rgba(45, 47, 54, 0.95) !important; }
/* Four 16:9 cards a row in 20 px gutters: "1. Title" 15/700, two lines of 15/24 #DBDCDE, the runtime. */
@media (min-width: 641px) { [data-slot="detail.episodes"] [data-part="episodes.grid"] { grid-template-columns: repeat(4, minmax(0, 1fr)) !important; gap: 32px 20px !important; } }
[data-slot="detail.episodes"] [data-part="episode"][data-variant="template"] { padding: 0 !important; border: 0 !important; border-radius: 12px !important; background: transparent !important; box-shadow: none !important; transform: none !important; }
[data-part="starlight.ep-art"] { margin-bottom: 12px; }
[data-part="starlight.ep-art"]::before {
  content: ""; grid-area: 1 / 1; z-index: 2; place-self: center; width: 48px; height: 48px; border-radius: 50%; opacity: 0; transition: opacity 0.3s ease-out;
  background: rgba(0, 0, 0, 0.5) url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20fill%3D%27%23fff%27%20d%3D%27M8%205v14l11-7z%27%2F%3E%3C%2Fsvg%3E") center / 24px no-repeat;
}
