[data-slot="detail.episodes"] [data-part="episode"][data-state="watched"] [data-part="starlight.ep-art"] { opacity: 0.6; }
/* Suggested: posters in 20 px gutters; Details: 20/700 section titles. */
@media (min-width: 641px) {
  [data-slot="detail.recommended"], [data-slot="detail.relations"] { display: grid !important; grid-template-columns: repeat(auto-fill, minmax(224px, 1fr)); gap: 24px 20px !important; }
  [data-slot="detail.recommended"] > *, [data-slot="detail.relations"] > *, [data-part="relation"] > div { width: auto !important; min-width: 0; }
}
[data-slot="detail"] [data-part="fact.label"] { color: #fff; font-size: 15px; font-weight: 700; line-height: 24px; }
[data-slot="detail"] [data-part="fact.value"] { color: var(--sl-grey) !important; font-size: 15px; line-height: 24px; }
[data-part="detail.section-title"], [data-part="detail.heading"] { color: #fff; font-size: 20px !important; font-weight: 700 !important; line-height: 28px; }
[data-slot="detail"] [data-part="detail.synopsis"] { color: var(--sl-grey); }
/* Loading a title: the bare page with a centred teal ring, then the page fades in over .2 s. */
[data-slot="detail"] > * { transition: opacity 0.2s; }
[data-slot="detail"][data-pending] > * { opacity: 0 !important; }
[data-slot="detail"][data-pending]::after {
  content: ""; position: fixed; z-index: 40; top: 50%; left: 50%; width: 40px; height: 40px; margin: -20px 0 0 -20px; border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(5, 163, 194, 0), #05a3c2 70%, #3fd6f2);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3.5px)); mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3.5px));
  animation: starlight-spin 0.8s linear infinite;
}
@keyframes starlight-spin { to { transform: rotate(1turn); } }

/* ── Search: a borderless 32/700 field over a 3 px rule (48 px in for the glass), five 16:9 tiles a row. ── */
@media (min-width: 641px) {
