  [data-slot="search"] [data-part="search.field"] {
    flex: 1 0 100% !important; height: auto !important; padding: 0 0 16px 48px !important; border: 0 !important; border-bottom: 3px solid rgba(255, 255, 255, 0.5) !important;
    border-radius: 0 !important; background: transparent url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27%23fff%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%3E%3Ccircle%20cx%3D%2711%27%20cy%3D%2711%27%20r%3D%277%27%2F%3E%3Cpath%20d%3D%27m20%2020-4-4%27%2F%3E%3C%2Fsvg%3E") left 0 top 4px / 32px no-repeat !important;
    box-shadow: none !important; color: #fff; font-size: 32px !important; font-weight: 700; line-height: 40px;
  }
  [data-slot="search"] [data-part="search.grid"][data-variant="grid"] { grid-template-columns: repeat(5, minmax(0, 1fr)) !important; gap: 32px 20px !important; }
}
[data-slot="search"] [data-part="search.field"]::placeholder { color: #fafafa; opacity: 1; }
[data-part="search.filter"] { height: 35px; padding: 0 16px !important; border: 0 !important; border-radius: 18px !important; background: var(--sl-tile) !important; color: var(--sl-grey) !important; font-size: 15px !important; font-weight: 400 !important; box-shadow: none !important; }
[data-part="search.filter"][data-active] { background: #fff !important; color: #000 !important; }
[data-slot="search"] [data-part="search.grid"][data-state="loading"] > * { border-radius: 12px; background: var(--sl-back) !important; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.1); animation: none !important; }

/* ── Player: back + the title and "S1:E1 Title" at the top left, centred rewind · play · forward, a 4 px
   rgba(255,255,255,.2) track with the white fill and a 15 px white knob, the time left at its end. ── */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.top"] { padding: 20px 36px !important; background: linear-gradient(rgba(0, 0, 0, 0.6), transparent) !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="back"] { width: 40px; height: 40px; padding: 0 !important; justify-content: center; border-radius: 8px !important; background: transparent !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="back"]:hover { background: rgba(255, 255, 255, 0.1) !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="back"] > span { display: none; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="back"] svg { width: 32px; height: 32px; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.bottom"] {
  top: 0; display: flex; flex-direction: column; justify-content: flex-end; padding: 0 36px 24px !important;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.7), transparent 220px), linear-gradient(rgba(0, 0, 0, 0.5), transparent 160px) !important;
}
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.heading"] { position: absolute; top: 20px; left: 96px; right: 160px; text-shadow: none !important; }
[data-part="player.title"] { color: #efefef !important; font-size: 24px !important; font-weight: 700 !important; line-height: 28px !important; }
[data-part="player.episode"] { color: #fff !important; font-size: 15px !important; font-weight: 700 !important; line-height: 24px !important; letter-spacing: 0.11px; }
[data-part="player.episode"][data-season] [data-part="player.episode.number"]::before { content: "S" attr(data-season) ":"; }
[data-part="player.episode"][data-season] [data-part="player.episode.number"] { font-size: 0; }
[data-part="player.episode"][data-season] [data-part="player.episode.number"]::before, [data-part="player.episode"][data-season] [data-part="player.episode.number"]::after { font-size: 15px; }
[data-part="player.episode"][data-season] [data-part="player.episode.number"]::after { content: "E" attr(data-season-episode); }
[data-part="player.episode"]:has([data-part="player.episode.number"]):not([data-season]) [data-part="player.episode.number"] { font-size: 15px; }
[data-part="player.seekbar.track"] { height: 4px !important; border-radius: 6px; background: rgba(255, 255, 255, 0.2) !important; -webkit-backdrop-filter: blur(25px); backdrop-filter: blur(25px); }
[data-part="player.seekbar.buffer"] { height: 4px !important; background: rgba(255, 255, 255, 0.2) !important; }
[data-part="player.seekbar.fill"] { height: 4px !important; background: #fff !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.seekbar.knob"] { width: 15px !important; height: 15px !important; opacity: 1 !important; background: #fff !important; }
[data-part="player.seekbar"]:hover [data-part="player.seekbar.knob"] { scale: 1.2; transition: scale 0.15s; }
[data-part="player.time"] { color: #fff !important; font-family: inherit !important; font-size: 15px !important; font-weight: 400; }
[data-part="player.time"][data-variant="remaining"] { width: auto !important; min-width: 48px; text-align: right; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] { position: relative; min-height: 56px; margin-top: 12px !important; gap: 20px !important; }
[data-slot="player.controls"][data-variant="desktop"] :is([data-part="player.transport"], [data-part="player.actions"]) { display: contents; }
/* Rewind 10 · Play (48 px) · Forward 10 centred on the video; the rest at the right, 52 px apart. */
[data-slot="player.controls"][data-variant="desktop"] [data-control="play"] { position: absolute; left: calc(50% - 24px); width: 48px !important; height: 48px !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="play"] svg { width: 40px; height: 40px; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="rewind"] { position: absolute; left: calc(50% - 24px - 48px - 40px); }
[data-slot="player.controls"][data-variant="desktop"] [data-control="forward"] { position: absolute; left: calc(50% + 24px + 40px); }
[data-slot="player.controls"][data-variant="desktop"] :is([data-control="rewind"], [data-control="forward"]) { width: 48px !important; height: 48px !important; }
[data-slot="player.controls"][data-variant="desktop"] :is([data-control="rewind"], [data-control="forward"]) svg { width: 32px; height: 32px; }
/* The groups are display: contents, so their children order in the row; wrapped controls are reached through
   the child of player.actions that holds them. */
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > * { order: 5; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :is([data-control="volume"], :has(> [data-control="volume"])) { order: 1; margin-left: auto; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="previous"] { order: 2; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="next"] { order: 3; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.actions"] > :is([data-control="options"], [data-control="comments"], :has(> [data-control="options"]), :has(> [data-control="tracks"])) { order: 4; }
[data-slot="player.controls"][data-variant="desktop"] [data-control="fullscreen"] { order: 6 !important; }
[data-slot="player.controls"][data-variant="desktop"] [data-part="player.row"] { column-gap: 12px !important; }
[data-slot="player.controls"][data-variant="desktop"] :is([data-part="player.control"], [data-part="button"][data-control]) { border-radius: 8px; }
/* Skip Intro: a bright white block, black caps. */
[data-part="player.skip"] {
  display: flex; align-items: center; gap: 10px; height: 56px; padding: 0 24px !important; border: 0 !important; border-radius: 4px !important;
  background: #fff !important; color: #000 !important; box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4) !important;
  font-size: 15px !important; font-weight: 700 !important; letter-spacing: 1.76px; text-transform: uppercase;
}
[data-part="player.skip"]::before { content: ""; width: 18px; height: 18px; background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M5%205v14l9-7zM14%205v14l9-7z%27%2F%3E%3C%2Fsvg%3E") center / contain no-repeat; }
[data-part="player.skip"]:hover { background: var(--sl-grey) !important; }

/* ── Phones keep the shared layout with 16 px gutters. ── */
@media (max-width: 640px) {
  [data-part="starlight.info"] { padding: 0 16px 44px !important; }
  [data-part="starlight.logo"] { width: 240px; height: 100px; }
  [data-part="starlight.synopsis"] { font-size: 16px !important; line-height: 24px; }
