}
[data-slot="detail"] [data-part="detail.actions"] > * { flex: none !important; }

/* ═══ TV (Android TV and Game mode): the 1920 canvas. ═══ */
:scope[data-surface="tv"] { --u: calc(100vw / 1920); }
/* Side rail: an icon column (centres at x=75, 88 px pitch) floating over the page; focused, a 405 px opaque
   #17171C panel over the content with caps labels from x=119 and a 3×42 white bar beside the focused one. */
:scope[data-surface="tv"] [data-slot="page"] { margin-left: 0 !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] {
  width: calc(var(--u) * 150) !important; padding: calc(var(--u) * 35) 0 calc(var(--u) * 48) !important; gap: 0 !important;
  background: transparent !important; box-shadow: none !important; filter: none !important; transition: width 0.25s ease-out, background-color 0.25s ease-out !important;
}
:scope[data-surface="tv"] [data-slot="nav.side"]:focus-within { width: calc(var(--u) * 405) !important; background: #17171c !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] > div:first-of-type { order: 99; margin: auto 0 0 !important; padding-left: calc(var(--u) * 55); }
:scope[data-surface="tv"] [data-slot="nav.side"] > div:empty { flex: 0 0 0 !important; padding: 0 !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item"], [data-part="nav.action"]) {
  position: relative; flex: none; width: 100% !important; height: calc(var(--u) * 88) !important; margin: 0 !important; padding: 0 0 0 calc(var(--u) * 63) !important;
  gap: calc(var(--u) * 32) !important; border-radius: 0 !important; background: transparent !important; box-shadow: none !important; color: rgba(255, 255, 255, 0.6) !important;
}
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item"], [data-part="nav.action"]) > span:first-child { width: calc(var(--u) * 24) !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item"], [data-part="nav.action"]) svg { width: calc(var(--u) * 26); height: calc(var(--u) * 26); animation: none !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item.label"], [data-part="nav.action.label"]) { font-size: calc(var(--u) * 22) !important; font-weight: 700 !important; letter-spacing: calc(var(--u) * 1.5); text-transform: uppercase; }
:scope[data-surface="tv"] [data-slot="nav.side"] [data-part="nav.item"][data-active] { color: #fbfffe !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item"], [data-part="nav.action"]):focus { color: #fff !important; background: transparent !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] :is([data-part="nav.item"], [data-part="nav.action"]):focus::after { content: ""; position: absolute; top: 50%; left: calc(var(--u) * 100); width: calc(var(--u) * 3); height: calc(var(--u) * 42); translate: 0 -50%; background: #fff; }
:scope[data-surface="tv"] [data-slot="nav.side"] [data-action="account"] { order: -1; height: calc(var(--u) * 120) !important; margin-bottom: calc(var(--u) * 28) !important; padding-left: calc(var(--u) * 51) !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] [data-action="account"] > span:first-child, :scope[data-surface="tv"] [data-slot="nav.side"] [data-action="account"] img { width: calc(var(--u) * 48) !important; height: calc(var(--u) * 48) !important; border-radius: 50% !important; }
:scope[data-surface="tv"] [data-slot="nav.side"] [data-action="account"]:focus img { box-shadow: 0 0 0 calc(var(--u) * 3) #17171c, 0 0 0 calc(var(--u) * 6) #fff; }
:scope[data-surface="tv"] [data-slot="nav.side"] [data-action="account"]:focus::after { display: none; }

/* Hero: ≈83% of the screen; the copy at x=150, PLAY at y 695–755, dots at y≈842, the rows from y≈869. */
:scope[data-surface="tv"] [data-slot="home.hero"][data-variant="template"] { --hero-bleed: calc(var(--u) * 224) !important; margin-top: 0 !important; }
:scope[data-surface="tv"] [data-slot="home.hero"][data-state="loading"] { margin-top: 0 !important; margin-bottom: calc(var(--u) * -224) !important; }
:scope[data-surface="tv"] [data-part="starlight.hero"]::after { background: linear-gradient(to top, #17171c 0%, rgba(23, 23, 28, 0.6) 22%, transparent 45%), linear-gradient(to right, rgba(23, 23, 28, 0.85) 0%, rgba(23, 23, 28, 0.4) 35%, transparent 60%) !important; }
:scope[data-surface="tv"] [data-part="starlight.info"] { width: calc(var(--u) * 800) !important; padding: 0 0 calc(var(--u) * 325) calc(var(--u) * 150) !important; }
:scope[data-surface="tv"] [data-part="starlight.badge"] { height: calc(var(--u) * 36); margin-bottom: calc(var(--u) * 20); padding: 0 calc(var(--u) * 10); font-size: calc(var(--u) * 20) !important; line-height: calc(var(--u) * 36); }
:scope[data-surface="tv"] [data-part="starlight.logo"] { width: calc(var(--u) * 340) !important; max-width: none !important; height: calc(var(--u) * 130); margin-bottom: calc(var(--u) * 20); }
:scope[data-surface="tv"] [data-part="starlight.title"] { font-size: calc(var(--u) * 64) !important; }
:scope[data-surface="tv"] [data-part="starlight.promo"] { margin-bottom: calc(var(--u) * 12); line-height: calc(var(--u) * 40); }
:scope[data-surface="tv"] [data-part="starlight.promo"] > * { font-size: calc(var(--u) * 30) !important; }
:scope[data-surface="tv"] [data-part="starlight.meta"] { gap: calc(var(--u) * 12) !important; margin-bottom: calc(var(--u) * 16); line-height: calc(var(--u) * 30); }
:scope[data-surface="tv"] [data-part="starlight.rating"] { height: calc(var(--u) * 30); padding: 0 calc(var(--u) * 8); font-size: calc(var(--u) * 18) !important; line-height: calc(var(--u) * 30); }
:scope[data-surface="tv"] [data-part="starlight.meta-text"] > * { color: #c9cacd; font-size: calc(var(--u) * 20) !important; }
:scope[data-surface="tv"] [data-part="starlight.desc"] { max-width: calc(var(--u) * 640); margin-bottom: calc(var(--u) * 32); }
:scope[data-surface="tv"] [data-part="starlight.synopsis"] { font-size: calc(var(--u) * 26) !important; line-height: calc(var(--u) * 40); }
:scope[data-surface="tv"] [data-part="starlight.actions"] { gap: calc(var(--u) * 20) !important; }
:scope[data-surface="tv"] :is([data-part="starlight.play"], [data-part="starlight.details"]) {
  min-width: calc(var(--u) * 151); height: calc(var(--u) * 60) !important; min-height: 0 !important; justify-content: center; padding: 0 calc(var(--u) * 28) !important; gap: calc(var(--u) * 10) !important;
  border-radius: calc(var(--u) * 6) !important; font-size: calc(var(--u) * 22) !important; letter-spacing: calc(var(--u) * 2);
}
:scope[data-surface="tv"] :is([data-part="starlight.play"], [data-part="starlight.details"]) svg { width: calc(var(--u) * 24); height: calc(var(--u) * 24); }
:scope[data-surface="tv"] :is([data-part="starlight.play"], [data-part="starlight.details"]):focus { background: #f3f3f3 !important; color: #17171c !important; box-shadow: none !important; transform: scale(1.04); outline: none !important; }
:scope[data-surface="tv"] [data-slot="home.hero"] [data-part="hero.indicator"] { bottom: calc(var(--u) * 233) !important; gap: calc(var(--u) * 32) !important; }
:scope[data-surface="tv"] [data-slot="home.hero"] [data-part="hero.dot.track"] { width: calc(var(--u) * 10) !important; height: calc(var(--u) * 10) !important; background: #90919a !important; }
:scope[data-surface="tv"] [data-slot="home.hero"] [data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: calc(var(--u) * 32) !important; }

/* Rows: 24/600 white titles at x=150, 32 px over the tiles; posters 297×416 (gap 41), 16:9 tiles 378×213 (gap 40).
   Focus scales a tile to 1.05 inside a 3 px white border, nothing else. */
